with filtered as (select *, initcap(trim(city)) as city_title, coalesce(region, 'OTHER') as region_filled from stores where opened_date > date '2023-11-03' and region is not null) select case when sqft >= 13973 then 'LARGE' else 'SMALL' end as sqft_tier, stddev_samp(sqft) as sqft_stddev, count(*) filter (where region = 'South') as south_rows, max(sqft) filter (where city = 'Bangkok') as bangkok_max_sqft, stddev_samp(sqft) as sqft_stddev_2, sum(case when region = 'West' then sqft else 0 end) as west_sqft, grouping(case when sqft >= 13973 then 'LARGE' else 'SMALL' end) as grouping_level from filtered group by rollup (case when sqft >= 13973 then 'LARGE' else 'SMALL' end);
